(()=>{const toggle=document.getElementById('tracker-toggle'),dialog=document.getElementById('creature-tracker-dialog');let timer;const selected=new Set();const copy={en:{title:'Creature tracker',choose:'Select creatures',search:'Search creature…',creature:'Creature',day:'Last day',week:'Last week',total:'Overall',kills:'Creatures killed',players:'Players killed',empty:'Select creatures from the dropdown to compare their statistics.'},pt:{title:'Tracker de criaturas',choose:'Selecionar criaturas',search:'Pesquisar criatura…',creature:'Criatura',day:'Último dia',week:'Última semana',total:'Total geral',kills:'Criaturas mortas',players:'Jogadores mortos',empty:'Marque criaturas no dropdown para comparar as estatísticas.'},es:{title:'Tracker de criaturas',choose:'Seleccionar criaturas',search:'Buscar criatura…',creature:'Criatura',day:'Último día',week:'Última semana',total:'Total general',kills:'Criaturas muertas',players:'Jugadores muertos',empty:'Selecciona criaturas para comparar sus estadísticas.'}};const words=()=>copy[document.documentElement.lang]||copy.en;const name=s=>s.startsWith('(')?s:s.replace(/\b\w/g,c=>c.toUpperCase());const num=n=>n<1000?String(n):Math.floor(n/1000).toLocaleString('de-DE')+'.'+Math.floor(n%1000/100)+'k';
dialog.classList.add('multi-tracker');dialog.innerHTML='<header><h2 id="tracker-title"></h2><button type="button" class="tracker-close" aria-label="Close">×</button></header><div class="multi-select"><button type="button" class="multi-trigger" aria-expanded="false"></button><div class="multi-menu" hidden><input type="search"><div class="multi-options"></div></div></div><div class="tracker-comparisons"></div>';
const trigger=dialog.querySelector('.multi-trigger'),menu=dialog.querySelector('.multi-menu'),search=menu.querySelector('input'),list=menu.querySelector('.multi-options'),results=dialog.querySelector('.tracker-comparisons');let menuTimer,menuVersion=0;
function setMenu(open){const version=++menuVersion;clearTimeout(menuTimer);trigger.setAttribute('aria-expanded',String(open));if(open){menu.hidden=false;requestAnimationFrame(()=>{if(version===menuVersion)menu.classList.add('visible')})}else{menu.classList.remove('visible');menuTimer=setTimeout(()=>{if(version===menuVersion)menu.hidden=true},600)}}
function render(){const w=words();dialog.querySelector('h2').textContent=w.title;trigger.textContent=w.choose+(selected.size?' ('+selected.size+')':'')+' ⌄';search.placeholder=w.search;search.setAttribute('aria-label',w.search);results.replaceChildren();if(!selected.size){const p=document.createElement('p');p.className='tracker-note';p.textContent=w.empty;results.append(p);return}const shell=document.createElement('div');shell.className='tracker-list-scroll';const table=document.createElement('table');table.className='tracker-compact-list';const head=document.createElement('thead'),hr=document.createElement('tr');for(const title of [w.creature,w.day,w.week,w.total]){const th=document.createElement('th');th.textContent=title;hr.append(th)}head.append(hr);table.append(head);const body=document.createElement('tbody');for(const record of KILL_STATS.entries.filter(r=>selected.has(r.raceName))){const row=document.createElement('tr'),cell=document.createElement('td'),label=document.createElement('span');label.className='tracker-race-name';const img=document.createElement('img');const src=RACE_IMAGES[record.raceName.toLowerCase()];img.src=src||Object.values(RACE_IMAGES)[0];if(record.raceName==='(fire/poison/energy)')img.dataset.elementCycle='true';img.alt='';if(!src)img.className='creature-watermark';label.append(img,document.createTextNode(name(record.raceName)));cell.append(label);row.append(cell);for(const key of ['lastDay','lastWeek','overall']){const td=document.createElement('td');const killed=document.createElement('span'),players=document.createElement('small');killed.textContent=/^humans?$/i.test(record.raceName)?'':num(record[key+'KilledByPlayers']);killed.title=w.kills;players.textContent=num(record[key+'KilledPlayers']);players.title=w.players;td.append(killed,players);row.append(td)}body.append(row)}table.append(body);shell.append(table);results.append(shell);const legend=document.createElement('p');legend.className='tracker-note';legend.textContent=w.kills+' / '+w.players;results.append(legend)}

for(const record of [...KILL_STATS.entries].sort((a,b)=>a.raceName.localeCompare(b.raceName))){const label=document.createElement('label');label.className='multi-option';const check=document.createElement('input');check.type='checkbox';check.value=record.raceName;check.onchange=()=>{check.checked?selected.add(record.raceName):selected.delete(record.raceName);render()};label.append(check);const src=RACE_IMAGES[record.raceName.toLowerCase()];{const img=document.createElement('img');img.src=src||Object.values(RACE_IMAGES)[0];if(record.raceName==='(fire/poison/energy)')img.dataset.elementCycle='true';img.alt='';img.loading='lazy';img.decoding='async';img.width=32;img.height=32;if(!src)img.className='creature-watermark';label.append(img)}const text=document.createElement('span');text.textContent=name(record.raceName);label.append(text);list.append(label)}
search.oninput=()=>{const q=search.value.toLowerCase().trim();list.querySelectorAll('label').forEach(label=>label.hidden=!label.textContent.toLowerCase().includes(q))};trigger.onclick=()=>setMenu(trigger.getAttribute('aria-expanded')!=='true');dialog.addEventListener('click',e=>{if(!e.target.closest('.multi-select'))setMenu(false)});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});function close(){if(!dialog.open)return;setMenu(false);dialog.classList.remove('visible');clearTimeout(timer);timer=setTimeout(()=>{dialog.close();toggle.focus({preventScroll:true})},600)}dialog.querySelector('.tracker-close').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();if(trigger.getAttribute('aria-expanded')==='true')setMenu(false);else close()});toggle.onclick=()=>{clearTimeout(timer);render();if(!dialog.open)dialog.showModal();requestAnimationFrame(()=>{if(dialog.open)dialog.classList.add('visible')})};document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{toggle.firstChild.textContent=words().choose+' ';render()}));toggle.firstChild.textContent=words().choose+' ';
})();


(()=>{const frames=[RACE_IMAGES['(fire/poison/energy)'],RACE_IMAGES._element_poison,RACE_IMAGES._element_energy];const mounted=new Set();function mount(){document.querySelectorAll('img[data-element-cycle]').forEach(img=>{if(img.closest('.element-crossfade'))return;const holder=document.createElement('span');holder.className='element-crossfade '+['element-fire','element-poison','element-energy'][index];const size=img.closest('.race-sprite')?52:32;holder.style.width=size+'px';holder.style.height=size+'px';img.replaceWith(holder);frames.forEach((src,i)=>{const layer=document.createElement('img');layer.src=src;layer.alt='';layer.className=i===index?'active':'';holder.append(layer)});mounted.add(holder)});for(const node of mounted)if(!node.isConnected)mounted.delete(node)}let index=0;const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');setInterval(()=>{if(document.hidden||reducedMotion.matches||![...mounted].some(holder=>holder.isConnected&&holder.getClientRects().length))return;index=(index+1)%3;for(const holder of mounted){holder.classList.remove('element-fire','element-poison','element-energy');holder.classList.add(['element-fire','element-poison','element-energy'][index]);holder.querySelectorAll('img').forEach((img,i)=>img.classList.toggle('active',i===index))}},4000);let mounting=false;new MutationObserver(records=>{if(mounting)return;for(const node of mounted)if(!node.isConnected)mounted.delete(node);if(!records.some(r=>[...r.addedNodes].some(node=>node.nodeType===1&&(node.matches?.('img[data-element-cycle]')||node.querySelector?.('img[data-element-cycle]')))))return;mounting=true;queueMicrotask(()=>{mounting=false;mount()})}).observe(document.body,{childList:true,subtree:true});mount();})();


